{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The background describes the current state of knowledge, noting limited evidence on evaluating sustainability of EBIs, and the discussion further describes existing syntheses and knowledge gaps."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "It is unclear which approach/approaches are most effective for evaluating sustainability and what measures and outcomes are most commonly used.",
      "reason": "The importance and need for the review are explained: uncertainty about which approaches are effective for evaluating sustainability, and implementation is 'meaningless without long-term sustainability efforts.'"
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "Similar reviews exist (e.g., Lennox et al. and other recent syntheses are cited) and the need for the current review is explained by its distinct focus on evaluation approaches."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of approaches used to evaluate sustainability, not a review of intervention effects, so describing a mechanism of action does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review examines evaluation approaches for sustainability rather than assessing a specific complex intervention, so a logic model of intervention components is not required."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The review objectives are explicitly stated in a dedicated Aim section, also echoed in the abstract."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "Integrative reviews can include diverse data sources and do not restrict the type of study design.",
      "reason": "This is an integrative review of approaches to evaluating sustainability, not a review of intervention effects, so PICO-formatted planned comparisons do not apply."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Articles were included if they: • Were published in a peer-review journal • Were primary research • Had explicit research design and data collection methods • Had an explicit theoretical approach for sustainability • Were within a healthcare setting • Evaluated the sustainability of an EBI",
      "reason": "Table 1 specifies study characteristics for eligibility including study design (primary research with explicit design), setting (healthcare, defined in footnote g), and requirement of an explicit theoretical approach and independent sustainability evaluation component."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "table_0",
      "quote": "• Were published in a peer-review journal ... Exclusion: • Were gray literature",
      "reason": "Publication status (peer-reviewed, no gray literature) is specified, and English-language restriction is mentioned only in the Limitations ('We only included published studies in the English language'), but no dissemination year restriction is reported in the eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "table_0",
      "quote": "Did not evaluate the sustainability of an EBI or QI intervention using a defined approach",
      "reason": "The review did not exclude studies based on outcome measurement or reporting; exclusions concerned absence of sustainability evaluation approaches, so the distinction between outcomes not measured versus not reported does not apply."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence specifies groups used in each synthesis or links them to review objectives; the review describes data analysis broadly without defining synthesis groupings."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "table_0",
      "quote": "Were within a healthcare setting g ... g Defined as a broad array of services and places where healthcare provision occurs, including acute care hospitals, urgent care centers...",
      "reason": "Some restrictions have rationale via defining footnotes (e.g., healthcare setting, theoretical approach definitions), but explicit rationales for notable restrictions such as excluding gray literature or requiring an independent sustainability evaluation component are not provided."
    }
  ],
  "confidence": 82
}

